css:
/* origami toggle */
.origami-toggle {
  --paper-color: #ffffff;
  --shadow-dark: #d1d1d6;
  --shadow-light: #ffffff;
  --accent-stone: #ffffff;
  --accent-clay: #000000;

  position: relative;
  display: inline-block;
  width: 100px;
  height: 50px;
  cursor: pointer;
}

.origami-toggle .origami-input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}
.origami-toggle .origami-paper {
  position: absolute;
  inset: 0;
  background-color: var(--paper-color);
  border-radius: 12px;
  box-shadow:
    6px 6px 12px var(--shadow-dark),
    -6px -6px 12px var(--shadow-light);
  transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
}
.origami-toggle .origami-fold {
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: var(--accent-clay);
  transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  transform: skewX(-15deg);
  opacity: 0;
}
.origami-toggle .origami-knob {
  position: absolute;
  top: 5px;
  left: 5px;
  width: 40px;
  height: 40px;
  background-color: var(--paper-color);
  border-radius: 8px;
  box-shadow:
    3px 3px 6px var(--shadow-dark),
    -3px -3px 6px var(--shadow-light);
  transition: all 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2;
}
.origami-toggle .origami-texture {
  width: 4px;
  height: 16px;
  background: var(--shadow-dark);
  border-radius: 10px;
  box-shadow:
    8px 0 var(--shadow-dark),
    -8px 0 var(--shadow-dark);
  transition: all 0.4s ease;
}
.origami-toggle .origami-input:checked + .origami-paper {
  box-shadow:
    inset 4px 4px 8px rgba(0, 0, 0, 0.3),
    0 8px 20px rgba(0, 0, 0, 0.2);
}

.origami-toggle .origami-input:checked + .origami-paper .origami-fold {
  left: 0;
  transform: skewX(0deg);
  opacity: 1;
}

.origami-toggle .origami-input:checked + .origami-paper .origami-knob {
  left: calc(100% - 45px);
  background-color: var(--accent-stone);
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.4);
  transform: rotate(90deg);
}

.origami-toggle
  .origami-input:checked
  + .origami-paper
  .origami-knob
  .origami-texture {
  background: #000000;
  box-shadow:
    8px 0 #000000,
    -8px 0 #000000;
  height: 4px;
}
.origami-toggle:active .origami-knob {
  transform: scale(0.85);
}
